import{z as o,x as B,o as i,c as d,q as s,j as p,D as l,d as t,s as E,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"PD 分离的 KV 传输","description":"","frontmatter":{"title":"PD 分离的 KV 传输","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pd-kv-transfer.md","filePath":"llm/pd-kv-transfer.md","lastUpdated":1791063341000}'),A={name:"llm/pd-kv-transfer.md"};function P(D,e,m,V,h,T){const r=B("Mermaid");return i(),d("div",null,[e[2]||(e[2]=s('<h1 id="pd-分离的-kv-传输" tabindex="-1">PD 分离的 KV 传输 <a class="header-anchor" href="#pd-分离的-kv-传输" aria-label="Permalink to &quot;PD 分离的 KV 传输&quot;">​</a></h1><div class="epigraph"><p>拆开 prefill 与 decode 之后，中间状态必须搬家：体积按层数 × 提示长度线性涨，传输要么被互连藏住，要么把 TTFT 吃回去。</p><footer>—— Zhong et al., DistServe 中的 KV 体积、带宽与分层放置；Patel et al., Splitwise 中的机间状态传输</footer></div><p><a href="/llm/pd-disaggregation">PD 分离</a> 把计算拆到两池，正确性要求 decode 看见与 prefill 同一套 KV。传输对象主要是每层的键值缓存，外加首 token 与少量元数据。DistServe 给过一个具体量级：OPT-66B、512 token 的 KV 约 1.13GB；若平均 10 请求/秒，需要约 11.3GB/s（约 90Gbps）才能让传输在流水线里「看不见」。现代训练集群常有数百 Gbps 级 InfiniBand 或节点内 NVLink（文中 A100 卡间峰值 600GB/s 量级），数字上够用，但<strong>只有放置对了才够用</strong>。跨节点带宽差时，必须把对应层段放进同一节点。Splitwise 同样把请求状态经 GPU 集群高速背板与优化过的网络库搬走。本篇写体积公式、同步还是分层重叠、pull 与突发，不把分离动机再写一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>KV 体积粗算为</p> \\[\\mathrm{bytes}\\approx L_{\\mathrm{layers}}\\times s_{\\mathrm{prompt}}\\times n_{\\mathrm{kv}}\\times d_h\\times 2\\times s_{\\mathrm{elem}}, \\]<p>因子 2 是 K 与 V。MHA 的 \\(n_{\\mathrm{kv}}\\) 等于查询头数；GQA 缩小它；<a href="/llm/mla">MLA</a> 吸收后变成短潜向量加小 RoPE 旁路，体积再降一档。未压缩的 66B 级、中等提示，已经是 GB 级；长文档摘要负载上 \\(s_{\\mathrm{prompt}}\\) 再乘数倍。传输时间 \\(\\approx\\) 体积 / 有效带宽。若它与 prefill 执行同量级，TTFT SLO 里就会出现一项 colocate 没有的税，分离的 goodput 优势被抹平。</p><p><span class="marginnote">数字实例：GQA 的省法是让多个查询头共用一组 K/V 头。比如 32 个查询头配 8 个 KV 头，公式里的 \\(n_{\\mathrm{kv}}\\) 从 32 变 8，KV 体积直接砍到四分之一——同一条链路能扛的请求率翻四倍，这就是它成为分离场景盟友的原因。</span></p><p>第二问题是与计算重叠。整包 KV 在 prefill 全部结束后再拷，延迟全加在首 token 之后、decode 开始之前。按层传输可以让浅层在深层还在算时就出发，但要求 P/D 的层到设备映射一致，且接收侧有缓冲。</p><h3 id="_90gbps-是例子不是门槛" tabindex="-1">90Gbps 是例子不是门槛 <a class="header-anchor" href="#_90gbps-是例子不是门槛" aria-label="Permalink to &quot;90Gbps 是例子不是门槛&quot;">​</a></h3><p>1.13GB × 10 rps 说明的是：<strong>请求率 × 单请求 KV</strong> 必须低于链路上的有效带宽。换模型、换精度、换提示长度，门槛线性变。FP16 与 FP8 KV、GQA、MLA，都会改同一公式里的因子。不要把 90Gbps 写成「PD 分离需要 90Gbps」；要写成「用公式代你的负载，再和 NVLink / IB 的有效带宽比」。DistServe 在 InfiniBand 充足时允许跨节点任意放置；不足时改用节点内算法。</p><p><span class="marginnote">有效带宽远小于标称峰值。PCIe 拷、NCCL 协议开销、双向流量、与计算争用，都会把 600GB/s 变成一小截。规划用实测拷贝带宽，不用宣传页。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>DistServe 的跨节点路径用 NCCL；节点内用异步 CudaMemcpy，避免拷贝阻塞 GPU 计算。传输采用 pull：decode 实例需要时再来取，prefill 实例把 KV 留在自己的 GPU 内存里当队列。这样 P 侧可以继续接下一个 prefill，不必等 D 侧立刻收完；突发时压力表现为 P 侧缓冲涨，而不是 D 侧 OOM。层与层之间 KV 独立：只在对应层之间搬。于是可以按 inter-op 分段，把 P 与 D 的同一阶段塞进同一节点，KV 强制走 NVLink。节点 GPU 数有限（常见 8），可枚举段内并行配置，用模拟器挑 goodput。</p><h3 id="splitwise-的机间状态" tabindex="-1">Splitwise 的机间状态 <a class="header-anchor" href="#splitwise-的机间状态" aria-label="Permalink to &quot;Splitwise 的机间状态&quot;">​</a></h3><p>Splitwise 把 prompt 机器上算完的 KV 发给 generation 机器，走集群背板。异构池上 P 卡与 D 卡可能不同代，传输库必须处理设备差异与拓扑。Mixed 池存在时，有的请求根本不搬家（两阶段在同一台），传输量为零——这是突发阀，也是对照实验里「分离税」的下界。无论哪篇，状态移动都发生在高速 GPU 互连上，而不是绕道主机内存再上以太网，除非实现有意做了降级。</p>',16)),(i(),p(n,null,{default:l(()=>[E(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20PF%5B%22Prefill%20%E9%80%90%E5%B1%82%E5%86%99%E5%87%BA%20KV%22%5D%20--%3E%20BUF%5B%22P%20%E4%BE%A7%20HBM%20%E7%BC%93%E5%86%B2%22%5D%0A%20%20BUF%20--%3E%20PULL%5B%22D%20%E4%BE%A7%E6%8C%89%E9%9C%80%20pull%22%5D%0A%20%20PULL%20--%3E%20MAP%7B%22%E5%AF%B9%E5%BA%94%E5%B1%82%E6%98%AF%E5%90%A6%E5%90%8C%E8%8A%82%E7%82%B9%22%7D%0A%20%20MAP%20--%3E%7C%E6%98%AF%7C%20NV%5B%22NVLink%20%2F%20%E5%BC%82%E6%AD%A5%E6%8B%B7%E8%B4%9D%22%5D%0A%20%20MAP%20--%3E%7C%E5%90%A6%7C%20IB%5B%22%E8%B7%A8%E8%8A%82%E7%82%B9%20NCCL%22%5D%0A%20%20NV%20--%3E%20D%5B%22Decode%20%E5%86%99%E5%85%A5%E6%9C%AC%E4%BE%A7%20KV%20%E6%B1%A0%22%5D%0A%20%20IB%20--%3E%20D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h3",{id:"与并行度的接口",tabindex:"-1"},[t("与并行度的接口 "),a("a",{class:"header-anchor",href:"#与并行度的接口","aria-label":'Permalink to "与并行度的接口"'},"​")],-1)),e[4]||(e[4]=a("p",null,"P 与 D 的 TP/PP/EP 可以不同，但传输层要会重排。PP 度不同：层到卡的映射表必须显式，不能假设「阶段 \\(i\\) 对阶段 \\(i\\)」。TP 度不同：按头切的 KV 要 gather 或重新切片后再发。EP 不切 KV（专家在 FFN），注意力侧布局才影响 KV 分片。MLA 潜向量更小，同样 rps 下带宽门槛按比例下降，长上下文分离更可行。投机解码的草稿 KV 一般只在 D 侧生存，不必从 P 传来。",-1)),e[5]||(e[5]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[6]||(e[6]=a("p",null,"分离把「干扰时间」换成「拷贝时间」。拷贝可以与下一请求的 prefill 重叠，也可以与本请求深层计算重叠，唯独不能与「decode 已经需要这一层 KV」重叠。Pull 模型把耦合从推送握手改成消费者驱动，P 与 D 的好put 各自闭环：P 满了就反压准入，D 满了就少 pull。这比两侧锁步更稳，代价是 P 侧要为未取走的 KV 留 HBM，挤占下一个 prefill 的 batch。",-1)),(i(),p(n,null,{default:l(()=>[E(r,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22P%20%E7%AE%97%E6%B5%85%E5%B1%82%20KV%22%5D%20--%3E%20OVL%5B%22%E6%B5%85%E5%B1%82%E6%8B%B7%E8%B4%9D%E4%B8%8E%E6%B7%B1%E5%B1%82%E8%AE%A1%E7%AE%97%E9%87%8D%E5%8F%A0%E5%87%BA%E5%8F%91%22%5D%0A%20%20P2%5B%22P%20%E7%BB%A7%E7%BB%AD%E7%AE%97%E6%B7%B1%E5%B1%82%20KV%22%5D%20--%3E%20OVL%0A%20%20OVL%20--%3E%20ARR%5B%22KV%20%E5%9C%A8%20D%20%E4%BE%A7%E5%88%B0%E9%BD%90%22%5D%0A%20%20ARR%20--%3E%20D1%5B%22decode%20%E9%A6%96%E6%AD%A5%E6%89%8D%E5%BC%80%E5%A7%8B%22%5D%0A%20%20BAD%5B%22%E6%95%B4%E5%8C%85%E7%AD%89%20prefill%20%E5%85%A8%E9%83%A8%E7%BB%93%E6%9D%9F%E5%90%8E%E5%86%8D%E6%8B%B7%22%5D%20--%3E%20ADD%5B%22%E4%BC%A0%E8%BE%93%E6%97%B6%E9%97%B4%E5%85%A8%E9%A2%9D%E8%AE%A1%E5%85%A5%20TTFT%22%5D%0A%20%20PULL%5B%22pull%EF%BC%9A%E6%8B%B7%E8%B4%9D%E8%BF%98%E5%8F%AF%E4%B8%8E%E4%B8%8B%E4%B8%80%E8%AF%B7%E6%B1%82%20prefill%20%E9%87%8D%E5%8F%A0%22%5D%20--%3E%20HIDE%5B%22%E4%BC%A0%E8%BE%93%E7%A8%8E%E8%A2%AB%E8%97%8F%E4%BD%8F%22%5D%0A"})]),fallback:l(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=s('<p><span class="marginnote">直觉类比：pull 像外卖柜——prefill 把做好的「餐」（KV）放进柜子（P 侧 HBM）就去接下一单，decode 顾客有空再来取。做餐的不被取餐卡住，突发时胀的是柜子不是后厨；但柜子占多了，后厨放下一单备菜的空间就被挤掉，这就是 P 侧 HBM 的代价。</span></p><p>带宽感知放置的机制是缩小「KV 必须走的最慢一跳」。同节点 NVLink 把 1.13GB 变成毫秒级以下（按峰值算更短），相对数百毫秒的 TTFT 可忽略。跨弱网把同一份数据变成几十毫秒到数秒，TTFT 直接破 SLO。因此算法先问拓扑，再问并行，而不是先搜出最优 \\(T,P\\) 再发现搬不动。</p><p><span class="marginnote">数字实例：同一份 1.13GB，走节点内 NVLink（有效带宽按打三折的 150GB/s 算）约 7.5 毫秒，对几百毫秒的 TTFT 几乎无感；换 25GB/s 级的跨节点弱链路就要约 45 毫秒起步，再叠排队就可能顶破 SLO。同一包数据，放置决定传输税是「看不见」还是「主显」。</span></p><p><span class="marginnote">TTFT 应包含「直到 decode 侧具备生成第二个 token 所需的 KV」。只测 P 侧算完会低估延迟，分离看起来毫无传输税。评测探针要打在用户可见的首包之后的稳定 TPOT 起点。</span></p><h3 id="压缩与量化是传输旋钮" tabindex="-1">压缩与量化是传输旋钮 <a class="header-anchor" href="#压缩与量化是传输旋钮" aria-label="Permalink to &quot;压缩与量化是传输旋钮&quot;">​</a></h3><p>GQA、MLA、KV 量化同时减小 HBM 与传输体积，是分离的盟友。它们也减小 colocate 的显存压力，所以不是分离专属。分离场景下，传输路径上的量化必须在 D 侧可反量化或与 D 侧计算精度一致，否则数值漂。DistServe / Splitwise 正文不依赖某一种 KV 量化方案；工程上多出来的格式转换时间要计入传输税。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>互连弱、KV 大、rps 高，三者叠在一起时不要分离，或只在节点内分离（P/D 共节点不同卡）。超长上下文先考虑压缩 KV，再考虑拆池。失败恢复：P 侧算完但 D 侧没收到，要重传或重计算；不能假设 NCCL 一次成功。安全上 KV 含提示信息，传输通道与落盘缓冲按机密数据管理，这与算法无关但属于部署清单。</p><p>不要把 PagedAttention 的页表原样 RDMA 到另一台：页在源设备虚拟地址里，目标要按自己的块池重建。实现上通常是按层、按块打包，而不是搬页表指针。不要给 KV 传输伪造独立 arXiv；体积与 90Gbps 例子、NCCL / CudaMemcpy、pull、同阶段共节点，都写在 DistServe（arXiv:2401.09670）里。Splitwise（arXiv:2311.18677）给出背板传输与异构机的对照。后续缓存中心架构是别的系统，本篇不把它们的数字安到这两篇上。</p><p><span class="marginnote">调试「分离后 TTFT 变差」先画三张时间线：P 执行、拷贝、D 首步。哪一段涨就对哪一段：执行涨是并行搜错了，拷贝涨是放置或体积，D 首步涨是 pull 排队或 D 侧 batch 策略。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PD 分离的中间状态以 KV 为主，体积随层数、提示长、KV 头数、精度线性涨。</li><li>DistServe 用 OPT-66B、512 token ≈1.13GB 与 10 rps ≈90Gbps 说明带宽量级；门槛要按自己的负载重算。</li><li>节点内异步拷贝、跨节点 NCCL；按层对应传输；pull 用 P 侧 HBM 当队列。</li><li>弱跨节点带宽时，把同一 PP 阶段的 P/D 段放进同一节点，强制走 NVLink。</li><li>TP/PP 不同要对 KV 做重切片；MLA/GQA/量化降低传输税。</li><li>出处：Zhong et al., <em>DistServe</em>，arXiv:2401.09670；Patel et al., <em>Splitwise</em>，arXiv:2311.18677。</li></ul>',12))])}const c=o(A,[["render",P]]);export{u as __pageData,c as default};
